# Simple map format
# MAP <mapId>
# OBJECT <id> <type> <x> <y> <spritePath> <solid(0|1)>
# TRIGGER <id> <x> <y> <width> <height> <eventName>

MAP 0001_TestMap

OBJECT grass_01 untergrund -64 -64 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_02 untergrund 0 -64 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_03 untergrund 64 -64 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_04 untergrund -64 0 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_05 untergrund 0 0 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_06 untergrund 64 0 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_07 untergrund -64 64 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_08 untergrund 0 64 Assets/Sprites/Environment/basic_grass.png 0
OBJECT grass_09 untergrund 64 64 Assets/Sprites/Environment/basic_grass.png 0

OBJECT rock_01 scenery -192 -64 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_02 scenery -128 -64 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_03 scenery 64 -128 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_04 scenery 192 -64 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_05 scenery -192 128 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_06 scenery -64 128 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_07 scenery 128 128 Assets/Sprites/Environment/basic_rock.png 1
OBJECT rock_08 scenery 256 192 Assets/Sprites/Environment/basic_rock.png 1

TRIGGER spawn_area -80 -80 160 160 Trigger_SpawnArea
TRIGGER north_path -64 -260 220 120 Trigger_NorthPath